import java.io.File;
import java.nio.file.Path;
import java.nio.file.Paths;

public class ImportingUtilities {

    // other methods

    /**
     * Creates a unique file inside {@code dir} using {@code name}. The method
     * protects against directory‑traversal attacks by normalizing the supplied
     * name and ensuring that the resolved path stays within {@code dir}.
     *
     * @param dir  the target directory (must not be {@code null})
     * @param name the desired file name (may contain query parameters)
     * @return a {@link File} instance that does not yet exist
     * @throws IllegalArgumentException if the name would resolve outside {@code dir}
     */
    static public File allocateFile(File dir, String name) {
        if (dir == null) {
            throw new IllegalArgumentException("Target directory cannot be null");
        }

        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths and leading separators
        Path rawPath = Paths.get(name);
        if (rawPath.isAbsolute() || name.startsWith("/") || name.startsWith("\\")) {
            throw new IllegalArgumentException("Absolute paths are not allowed");
        }

        // Normalize the supplied name to collapse any ".." or "." segments
        Path normalizedName = rawPath.normalize();

        // Resolve against the target directory and verify containment
        Path targetPath = dir.toPath().resolve(normalizedName).normalize();
        if (!targetPath.startsWith(dir.toPath().normalize())) {
            throw new IllegalArgumentException(
                "Zip archives with files escaping their root directory are not allowed");
        }

        // Prepare prefix/suffix for duplicate handling
        String sanitized = normalizedName.toString();
        int dot = sanitized.lastIndexOf('.');
        String prefix = dot < 0 ? sanitized : sanitized.substring(0, dot);
        String suffix = dot < 0 ? "" : sanitized.substring(dot);

        File file = targetPath.toFile();
        int index = 2;
        while (file.exists()) {
            file = new File(dir, prefix + "-" + index++ + suffix);
        }

        // Ensure parent directories exist
        file.getParentFile().mkdirs();

        return file;
    }

    // other methods
}
```

