        int i = 0;
        while (i < path.length() && path.charAt(i) == '/') {
            i++;
        }

        // Keep at most one leading slash
        String normalized = (i > 1) ? path.substring(i - 1) : path;

        // If the resulting string is empty, represent the root path
        if (normalized.isEmpty()) {
