import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.regex.Pattern;

public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /* Regular expression that matches valid locale identifiers.
       Examples of accepted formats: "en", "en_US", "en_US_POSIX".
       The pattern allows 1–3 components separated by underscores,
       each component consisting of alphabetic characters only. */
    private static final Pattern LOCALE_PATTERN =
            Pattern.compile("^[a-zA-Z]{2}(_[a-zA-Z]{2}){0,2}$");

    // other methods

    /**
     * Creates a Locale object from the request param, which might
     * be already a Locale or a String. Input is validated against
     * a whitelist of acceptable locale formats to prevent XSS
     * and other injection attacks.
     *
     * @param requestedLocale the parameter from the request
     * @return the Locale or {@code null} if the input is invalid
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        Locale locale = null;

        if (requestedLocale instanceof Locale) {
            locale = (Locale) requestedLocale;
        } else {
            String localeStr = requestedLocale.toString().trim();

            if (isValidLocaleString(localeStr)) {
                locale = LocalizedTextUtil.localeFromString(localeStr, null);
            } else {
                LOG.warn("Received invalid locale format: {}", localeStr);
            }
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

    /**
     * Validates that the supplied string conforms to the expected
     * locale format defined by {@link #LOCALE_PATTERN}. This method
     * acts as a whitelist filter, rejecting any input that does not
     * match the pattern and thereby mitigating potential XSS or
     * injection attacks.
     *
     * @param localeStr the locale string to validate
     * @return {@code true} if the string matches the pattern, otherwise {@code false}
     */
    private boolean isValidLocaleString(String localeStr) {
        return localeStr != null && LOCALE_PATTERN.matcher(localeStr).matches();
    }

    // other methods

}
