public class DefaultActionMapper implements ActionMapper {

    private static final Logger LOG = LoggerFactory.getLogger(DefaultActionMapper.class);

    /* A strict whitelist pattern that allows only alphanumeric characters,
       dots, underscores, slashes, exclamation marks and hyphens. */
    private static final Pattern ALLOWED_ACTION_NAMES =
            Pattern.compile("[a-zA-Z0-9._!\\/-]*");

    /* A safe fallback action name that is guaranteed to be valid. */
    private static final String DEFAULT_ACTION_NAME = "default";

    // other methods

    /**
     * Validates the action name against a whitelist. If the name does not
     * conform to the allowed pattern, it is rejected and a safe default
     * action name is returned. This prevents partial sanitisation that
     * could otherwise leave malicious characters in the resulting name.
     *
     * @param rawActionName action name extracted from URI
     * @return a validated action name or a safe default
     */
    protected String cleanupActionName(final String rawActionName) {
        if (rawActionName == null) {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Received null action name, using default action.");
            }
            return DEFAULT_ACTION_NAME;
        }

        if (ALLOWED_ACTION_NAMES.matcher(rawActionName).matches()) {
            return rawActionName;
        } else {
            if (LOG.isWarnEnabled()) {
                LOG.warn("Action/method [{}] does not match allowed action names pattern [{}], using default action.",
                        rawActionName, ALLOWED_ACTION_NAMES.pattern());
            }
            // Reject the invalid name and return a safe default
            return DEFAULT_ACTION_NAME;
        }
    }

    // other methods

}
