private LdapContext getLdapContextUsingStartTls(LdapContextFactory ldapContextFactory,
                                                Object principal,
                                                Object credentials) throws NamingException {

    if (!(ldapContextFactory instanceof JndiLdapContextFactory)) {
        throw new IllegalArgumentException("Unsupported LdapContextFactory type");
    }
    if (principal == null || credentials == null) {
        throw new IllegalArgumentException("Principal and credentials must not be null");
    }
    if (!(principal instanceof String) || !(credentials instanceof String)) {
        throw new IllegalArgumentException("Principal and credentials must be Strings");
    }
    String user = ((String) principal).trim();
    String pass = ((String) credentials).trim();
    if (user.isEmpty() || pass.isEmpty()) {
        throw new IllegalArgumentException("Principal and credentials must not be empty");
    }

    JndiLdapContextFactory jndiLdapContextFactory = (JndiLdapContextFactory) ldapContextFactory;
    Hashtable<String, Object> env = new Hashtable<>();
    env.put(Context.INITIAL_CONTEXT_FACTORY, jndiLdapContextFactory.getContextFactoryClassName());
    env.put(Context.PROVIDER_URL, jndiLdapContextFactory.getUrl());

    // Set authentication parameters *before* creating the context to ensure the server
    // performs a real bind once the TLS channel is established.
    env.put(Context.SECURITY_AUTHENTICATION, jndiLdapContextFactory.getAuthenticationMechanism());
    env.put(Context.SECURITY_PRINCIPAL, user);
    env.put(Context.SECURITY_CREDENTIALS, pass);

    LdapContext ctx = null;
    StartTlsResponse tls = null;
    try {
        ctx = new InitialLdapContext(env, null);

        // Negotiate STARTTLS
        StartTlsRequest startTlsRequest = new StartTlsRequest();
        tls = (StartTlsResponse) ctx.extendedOperation(startTlsRequest);
        if (tls == null) {
            throw new NamingException("STARTTLS negotiation failed: response was null");
        }
        tls.negotiate();

        // Force a simple operation to trigger authentication validation
        // If credentials are invalid, a NamingException will be thrown.
        ctx.getNameInNamespace();

        return ctx;
    } catch (CommunicationException | NamingException e) {
        LdapUtils.closeContext(ctx);
        if (tls != null) {
            try { tls.close(); } catch (Exception ignored) {}
        }
        securityLog.error(withRealm(
                "Failed to establish authenticated TLS connection with '%s': %s",
                server(jndiLdapContextFactory),
                e.getMessage()));
        throw e;
    } catch (Throwable t) {
        LdapUtils.closeContext(ctx);
        if (tls != null) {
            try { tls.close(); } catch (Exception ignored) {}
        }
        securityLog.error(withRealm(
                "Unexpected failure to establish authenticated TLS connection with '%s': %s",
                server(jndiLdapContextFactory),
                t.getMessage()));
        throw t;
    }
}
