private int readStored(final byte[] buffer, final int offset, final int length) throws IOException {
    // Basic argument validation – defensive programming for production use
    if (buffer == null) {
        throw new NullPointerException("buffer");
    }
    if (offset < 0 || length < 0 || offset + length > buffer.length) {
        throw new IndexOutOfBoundsException(
                "offset=" + offset + ", length=" + length + ", buffer.length=" + buffer.length);
    }
    if (length == 0) {
        return 0;
    }

    // Ensure we have a valid entry context
    if (current == null || current.entry == null) {
        throw new IOException("No current entry available");
    }

    // Handle entries that use a data descriptor – they are cached separately
    if (current.hasDataDescriptor) {
        if (lastStoredEntry == null) {
            readStoredEntry(); // cache the entry
        }
        return lastStoredEntry.read(buffer, offset, length);
    }

    final long csize = current.entry.getSize();

    // Size must be known and non‑negative for STORED entries
    if (csize < 0) {
        throw new IOException("Invalid entry size: " + csize);
    }
    if (csize == 0) {
        return -1; // nothing to read
    }

    // End‑of‑entry already reached?
    if (current.bytesRead >= csize) {
        return -1;
    }

    // Refill the internal buffer if it is exhausted
    while (buf.remaining() == 0 && current.bytesRead < csize) {
        buf.position(0);
        int l = in.read(buf.array());
        if (l == -1) {
            // Unexpected EOF – treat as end of entry
            return -1;
        }
        if (l == 0) {
            // Avoid infinite loop on non‑blocking streams that return 0
            continue;
        }
        buf.limit(l);
        count(l);
        current.bytesReadFromStream += l;
    }

    // Determine how many bytes to copy to the caller
    int toRead = Math.min(buf.remaining(), length);
    long remaining = csize - current.bytesRead;
    if (remaining < toRead) {
        toRead = (int) remaining;
    }
    if (toRead <= 0) {
        return -1;
    }

    buf.get(buffer, offset, toRead);
    current.bytesRead += toRead;
    return toRead;
}
