public class ObjectArrayCodec implements ObjectSerializer, ObjectDeserializer {

    /* --------------------------------------------------------------------- */
    /*  Whitelist of safe component types                                   */
    /* --------------------------------------------------------------------- */

    /** Set of component classes that are considered safe for deserialization. */
    private static final Set<Class<?>> SAFE_COMPONENT_TYPES =
            Collections.unmodifiableSet(new HashSet<Class<?>>(
                    Arrays.asList(
                            Byte.class,
                            Short.class,
                            Integer.class,
                            Long.class,
                            Float.class,
                            Double.class,
                            Boolean.class,
                            Character.class,
                            String.class,
                            java.math.BigDecimal.class,
                            java.math.BigInteger.class,
                            java.util.Date.class,
                            java.time.LocalDate.class,
                            java.time.LocalDateTime.class,
                            java.time.Instant.class
                    )));

    /**
     * Checks whether a component class is allowed for deserialization.
     *
     * @param cls the component class to check
     * @return {@code true} if the class is a primitive or present in the whitelist
     */
    private static boolean isSafeComponentClass(Class<?> cls) {
        return cls.isPrimitive() || SAFE_COMPONENT_TYPES.contains(cls);
    }

    /* --------------------------------------------------------------------- */
    /*  Deserialization logic                                                 */
    /* --------------------------------------------------------------------- */

    @SuppressWarnings({ "unchecked", "rawtypes" })
    public <T> T deserialze(DefaultJSONParser parser, Type type, Object fieldName) {

        final JSONLexer lexer = parser.lexer;

        /* Handle JSON null */
        if (lexer.token() == JSONToken.NULL) {
            lexer.nextToken(JSONToken.COMMA);
            return null;
        }

        /* Handle JSON string literal → byte[] */
        if (lexer.token() == JSONToken.LITERAL_STRING) {
            byte[] bytes = lexer.bytesValue();
            lexer.nextToken(JSONToken.COMMA);
            return (T) bytes;
        }

